-- Importar la temporada 2026/27. Cambia TU_CORREO por el correo con el que te registraste en la web.
do $$
declare uid uuid; code text;
begin
  select id into uid from auth.users where email = lower('TU_CORREO@gmail.com');
  if uid is null then raise exception 'No existe ese correo: registrate primero en la web'; end if;
  if exists (select 1 from public.seasons_meta where season_id='2026-27') then raise exception 'La temporada 2026-27 ya existe'; end if;
  code := public.gen_join_code();
end $$;
